package com.familygrowth.infrastructure;
import com.familygrowth.application.*;import com.familygrowth.domain.Stage26DataRightsModels.*;import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository class JdbcStage26DataRightsStore implements Stage26DataRightsStore {private final JdbcTemplate jdbc;JdbcStage26DataRightsStore(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Override public Map<String,Object> exportFacts(UUID family,UUID child){requireChild(family,child);Map<String,Object> profile=jdbc.query("SELECT display_name,birth_date,age_stage FROM child_profile WHERE family_id=? AND id=?",r->{r.next();return Map.of("displayName",r.getString(1),"birthDate",r.getDate(2).toLocalDate().toString(),"ageStage",r.getString(3));},family,child);Map<String,Object> learning=new LinkedHashMap<>();learning.put("assignments",count("SELECT COUNT(*) FROM lesson_assignment WHERE family_id=? AND child_id=?",family,child));learning.put("attempts",count("SELECT COUNT(*) FROM activity_attempt a JOIN lesson_assignment l ON l.id=a.assignment_id WHERE a.family_id=? AND l.child_id=?",family,child));learning.put("completions",count("SELECT COUNT(*) FROM learning_completion c JOIN lesson_assignment l ON l.id=c.assignment_id WHERE l.family_id=? AND l.child_id=?",family,child));learning.put("seniorGoals",count("SELECT COUNT(*) FROM senior_weekly_goal WHERE family_id=? AND child_id=?",family,child));learning.put("seniorReflections",count("SELECT COUNT(*) FROM senior_reflection WHERE family_id=? AND child_id=?",family,child));learning.put("growthPlans",count("SELECT COUNT(*) FROM growth_plan WHERE family_id=? AND child_id=?",family,child));learning.put("growthMilestones",count("SELECT COUNT(*) FROM growth_milestone WHERE family_id=? AND child_id=?",family,child));learning.put("growthArtifacts",jdbc.query("SELECT id,milestone_id,content_type,byte_size,sha256,alt_text,created_at FROM growth_artifact WHERE family_id=? AND child_id=? ORDER BY created_at",(r,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getObject(1,UUID.class));m.put("milestoneId",r.getObject(2,UUID.class));m.put("contentType",r.getString(3));m.put("byteSize",r.getLong(4));m.put("sha256",r.getString(5));m.put("altText",r.getString(6));m.put("createdAt",r.getTimestamp(7).toInstant());return m;},family,child));Map<String,Object> usage=Map.of("events",count("SELECT COUNT(*) FROM usage_event WHERE family_id=? AND child_id=?",family,child),"appMinutes",number("SELECT COALESCE(SUM(minutes),0) FROM usage_event WHERE family_id=? AND child_id=? AND event_type='APP_ACTIVE'",family,child).longValue(),"learningMinutes",number("SELECT COALESCE(SUM(minutes),0) FROM usage_event WHERE family_id=? AND child_id=? AND event_type='LEARNING'",family,child).longValue());Map<String,Object> finance=jdbc.query("SELECT money_balance,reserved_money,coin_balance FROM wallet WHERE family_id=? AND child_id=?",r->{r.next();Map<String,Object> m=new LinkedHashMap<>();m.put("moneyBalance",r.getBigDecimal(1));m.put("reservedMoney",r.getBigDecimal(2));m.put("coinBalance",r.getLong(3));m.put("ledgerEntries",count("SELECT COUNT(*) FROM ledger_entry WHERE family_id=? AND child_id=?",family,child));return m;},family,child);return Map.of("profile",profile,"learning",learning,"usage",usage,"finance",finance);}
 @Override public Optional<StoredRequest> byKey(UUID family,String key){return jdbc.query("SELECT * FROM child_data_request WHERE family_id=? AND idempotency_key=?",this::row,family,key).stream().findFirst();}
 @Override public Optional<StoredRequest> byId(UUID family,UUID id){return jdbc.query("SELECT * FROM child_data_request WHERE family_id=? AND id=?",this::row,family,id).stream().findFirst();}
 @Override public StoredRequest create(UUID family,UUID child,UUID actor,String type,String tokenHash,Instant expires,String key,String payloadHash,Instant now){requireChild(family,child);UUID id=UUID.randomUUID();try{jdbc.update("INSERT INTO child_data_request(id,family_id,child_id,actor_id,request_type,status,confirmation_token_hash,confirmation_expires_at,idempotency_key,payload_hash,created_at) VALUES(?,?,?,?,?,'PREVIEWED',?,?,?,?,?)",id,family,child,actor,type,tokenHash,ts(expires),key,payloadHash,ts(now));}catch(DuplicateKeyException conflict){return byKey(family,key).orElseThrow(()->conflict);}return byId(family,id).orElseThrow();}
 @Override public void recordExport(UUID family,UUID child,UUID request,UUID actor,Instant now){try{jdbc.update("INSERT INTO child_data_action(id,family_id,child_id,actor_id,action_type,request_id,detail,created_at) VALUES(?,?,?,?,?,?,?,?)",UUID.randomUUID(),family,child,actor,"EXPORT_GENERATED",request,"schemaVersion=family-growth-child-export/1; excludes=secrets,answers,parent-private-notes",ts(now));jdbc.update("UPDATE child_data_request SET status='COMPLETED',completed_at=? WHERE family_id=? AND id=? AND status='PREVIEWED'",ts(now),family,request);}catch(DuplicateKeyException replay){}}
 @Override public StoredRequest completeErasure(UUID family,UUID child,UUID request,UUID actor,Instant now){StoredRequest current=jdbc.query("SELECT * FROM child_data_request WHERE family_id=? AND id=? FOR UPDATE",this::row,family,request).stream().findFirst().orElseThrow(FamilyGrowthService.NotFoundException::new);if(current.status().equals("COMPLETED"))return current;requireChild(family,child);jdbc.update("UPDATE child_profile SET display_name='已删除儿童',birth_date=DATE '1970-01-01',age_stage='INFANT_0_2',version=version+1 WHERE family_id=? AND id=?",family,child);jdbc.update("UPDATE child_experience_profile SET stage_override=NULL,override_reason='',haptics_enabled=FALSE,version=version+1,updated_at=? WHERE family_id=? AND child_id=?",ts(now),family,child);jdbc.update("UPDATE child_experience_audit SET old_birth_date=DATE '1970-01-01',new_birth_date=DATE '1970-01-01',reason='[已删除]' WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE task_completion SET evidence_note='[已删除]',review_note='[已删除]' WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE learning_completion SET review_note='[已删除]' WHERE assignment_id IN (SELECT id FROM lesson_assignment WHERE family_id=? AND child_id=?)",family,child);jdbc.update("UPDATE activity_attempt SET response_text='[已删除]' WHERE assignment_id IN (SELECT id FROM lesson_assignment WHERE family_id=? AND child_id=?)",family,child);jdbc.update("UPDATE learning_support_event SET child_message='[已删除]',private_note='[已删除]' WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE senior_weekly_goal SET title='[已删除]',evidence_target='[已删除]',next_action='[已删除]',updated_at=? WHERE family_id=? AND child_id=?",ts(now),family,child);jdbc.update("UPDATE senior_reflection SET evidence_summary='[已删除]',next_action='[已删除]' WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE senior_module_action SET reason='[已删除]' WHERE family_id=? AND child_id=?",family,child);jdbc.update("DELETE FROM growth_artifact WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE growth_milestone SET title='[已删除]',observation='[已删除]',revision=revision+1,updated_at=? WHERE family_id=? AND child_id=?",ts(now),family,child);jdbc.update("UPDATE growth_plan_action SET reason='[已删除]' WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE growth_goal_action SET reason='[已删除]' WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE growth_plan SET title='[已删除]',description='[已删除]',target='[已删除]',version=version+1,updated_at=? WHERE family_id=? AND child_id=?",ts(now),family,child);jdbc.update("UPDATE growth_goal SET title='[已删除]',description='[已删除]',target='[已删除]',version=version+1,updated_at=? WHERE family_id=? AND plan_id IN (SELECT id FROM growth_plan WHERE family_id=? AND child_id=?)",ts(now),family,family,child);jdbc.update("UPDATE growth_task SET title='[已删除]',description='[已删除]',version=version+1 WHERE family_id=? AND goal_id IN (SELECT id FROM growth_goal WHERE family_id=? AND plan_id IN (SELECT id FROM growth_plan WHERE family_id=? AND child_id=?))",family,family,family,child);jdbc.update("UPDATE wish SET title='[已删除]',version=version+1 WHERE family_id=? AND child_id=?",family,child);jdbc.update("DELETE FROM usage_temporary_allowance WHERE family_id=? AND child_id=?",family,child);jdbc.update("DELETE FROM usage_event WHERE family_id=? AND child_id=?",family,child);jdbc.update("DELETE FROM usage_session_state WHERE family_id=? AND child_id=?",family,child);jdbc.update("UPDATE usage_policy SET zone_id='Asia/Shanghai',daily_limit_minutes=20,session_limit_minutes=10,rest_minutes=10,quiet_start='21:30:00',quiet_end='06:30:00',updated_at=? WHERE family_id=? AND child_id=?",ts(now),family,child);jdbc.update("UPDATE auth_session SET revoked_at=? WHERE family_id=? AND actor_role='CHILD' AND child_id=? AND revoked_at IS NULL",ts(now),family,child);jdbc.update("UPDATE child_data_request SET status='COMPLETED',completed_at=?,confirmation_token_hash=NULL WHERE family_id=? AND id=?",ts(now),family,request);jdbc.update("INSERT INTO child_data_action(id,family_id,child_id,actor_id,action_type,request_id,detail,created_at) VALUES(?,?,?,?,?,?,?,?)",UUID.randomUUID(),family,child,actor,"ERASURE_CONFIRMED",request,"Direct identifiers, free text, growth artifact binaries and non-financial usage details redacted or removed; ledger, audit, idempotency and minimal learning state retained",ts(now));return byId(family,request).orElseThrow();}
 private StoredRequest row(ResultSet r,int n)throws SQLException{return new StoredRequest(r.getObject("id",UUID.class),r.getObject("family_id",UUID.class),r.getObject("child_id",UUID.class),r.getObject("actor_id",UUID.class),r.getString("request_type"),r.getString("status"),r.getString("confirmation_token_hash"),instant(r,"confirmation_expires_at"),r.getString("idempotency_key"),r.getString("payload_hash"),instant(r,"created_at"),instant(r,"completed_at"));}private void requireChild(UUID family,UUID child){if(count("SELECT COUNT(*) FROM child_profile WHERE family_id=? AND id=?",family,child)!=1)throw new FamilyGrowthService.NotFoundException();}private int count(String sql,Object...args){return number(sql,args).intValue();}private Number number(String sql,Object...args){Number n=jdbc.queryForObject(sql,Number.class,args);return n==null?0:n;}private static Timestamp ts(Instant i){return i==null?null:Timestamp.from(i);}private static Instant instant(ResultSet r,String c)throws SQLException{Timestamp t=r.getTimestamp(c);return t==null?null:t.toInstant();}
}
